// th15_s6_b11 — Stage 6 BossCard7 純符「純粋な弾幕地獄」/ 純符「ピュアリーバレットヘル」
// 源: st06bs.ecl.txt Boss7(674-736) -> BossCard7(1821-1914) + at/at2/at2b/at3/at3b/at4.
// 外壳: 独立无敌外壳. control 段负责段事件; 真实 Boss 承载位置/框/发弹.
// 无 DPS 外壳: LIFE 恒定, 阶段推进只走原 TIME 条件 (1800/3600/5400); 卡在 TIME 7200 结束.
// 源 Boss() 入场充能期 flagSet(3) 禁体碰, Boss7 入口 flagClear(3); 本卡从 Boss7 入口开始,
// 故真实 Boss 保持体碰: set_hitbox(25) = 源 setHitbox(50,50), set_hurtbox(28) = 源 setHurtbox(56,56).
// Boss4_pos(576-585) 只是每帧 enm322(3,0); enm322 公开手册待核且无目标 API, 未接入, 见 report.
// 源入口的 drop/anm/playSound/章节 setChapter/unknown569 与 Boss4_pos 按共用/表现口径省略.

const TIME_LIMIT: int = 7484;
const OPENING_BUFFER: int = 120;

