// ---- 以下每个源发射器闭包各占一个 async 任务, 用自己的 shooter 槽 0 ----

// BossCard7_at (源 C=0): mode3 固定整周环, base pi/2 (整环等价), 每波 32px 随机极坐标偏移.
// type5/color2, 初速 2.0; etDist48 + ANIM 退位移 -4*2 => 净出生距离 40.
async sub at_ring() {
    var rank: int = global(GVAR_RANK);
    var cnt: int = 22;
    var pause: int = 30;
    if rank == 0 { cnt = 15; }
    if rank == 1 { cnt = 22; }
    if rank == 2 { cnt = 24; }
    if rank == 3 { cnt = 28; pause = 20; }
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, cnt, 1);
    sh_speed(0, 2fx, 0fx);
    sh_angle(0, 90deg, 0deg);   // 源 etAngle(pi/2,0): 整环相位固定
    sh_dist(0, 40fx);           // etDist48 - 4*2.0
    loop {
        sh_offset_rad(0, rand(65536) as angle, 32fx);   // 每波一次 %RANDRAD 偏移
        sh_fire(0);
        wait(pause);
    }
}

// BossCard7_at2 (源 C=1): mode3 整周环, base 每波随机; 绝对出弹点 (96,144) + 32px 随机极偏移.
// type5/color4. 初速 E/N 1.0, H 1.4, L 1.9; etDist48 - 4*v 为净出生距离.
async sub at2_ring() {
    var rank: int = global(GVAR_RANK);
    var cnt: int = 10;
    var spd: fx = 1fx;
    var net: fx = 44fx;
    var pause: int = 40;
    if rank == 0 { cnt = 7; }
    if rank == 1 { cnt = 10; }
    if rank == 2 { cnt = 10; spd = 1.4fx; net = 42.4fx; }
    if rank == 3 { cnt = 10; spd = 1.9fx; net = 40.4fx; pause = 30; }
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, cnt, 1);
    sh_speed(0, spd, 0fx);
    sh_dist(0, net);
    sh_offset_abs(0, 96fx, 144fx);   // 源 etOffsetAbs(96,144), 世界绝对点
    loop {
        sh_angle(0, rand(65536) as angle, 0deg);        // etAngle(%RANDRAD): 先抽环相位
        sh_offset_rad(0, rand(65536) as angle, 32fx);   // 再抽极偏移
        sh_fire(0);
        wait(pause);
    }
}

