// BossCard7_at4 (源 C=5): mode5 半路错开整周环, 24 路, base pi/2 + pi/24, 每 10 帧一波.
// type20/color3, 初速 4.0; etDist64 - 4*4 => 净出生距离 48. 无偏移/无随机.
async sub at4_ring() {
    sh_reset(0);
    sh_sprite(0, TH15_OVAL, 3);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 24, 1);
    sh_speed(0, 4fx, 0fx);
    sh_angle(0, 90deg + ((32768 / 24) as angle), 0deg);   // mode5: alpha + pi/N
    sh_dist(0, 48fx);                                     // etDist64 - 4*4.0
    loop {
        sh_fire(0);
        wait(10);
    }
}

// ---- 真实 Boss: 承载原 Boss7/BossCard7 排程 ----
async sub boss_main() {
    // Boss() 入口框 (setHurtbox(56,56)/setHitbox(50,50) -> 受击 r=28 / 体碰 r=25); lifeSet(8000) 由生成参数给.
    set_hitbox(25fx);
    set_hurtbox(28fx);
    set_invuln(65535);
    // Boss7 充能 wait 80+30+50 = 160; 两处 +2 章节计时门中 Boss7 的按章节状态省略,
    // BossCard7 timerReset 前的 +2/+2 = 4 保留 (anmPlay/playSound 纯表现省略, 时序保留)
    wait(160);
    wait(4);
    // timerReset(t0) 后 +90 首波 (BossCard7 +90 门 -> 脚本时间 94)
    wait(90);
    spawn at_ring();
    wait(1710);                                  // 到 TIME 1800
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // 源 etClear(640)
    spawn at2_ring();
    spawn at2b_ring();
    wait(1800);                                  // 到 TIME 3600
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // 源 etClear(640)
    spawn at3_ring();
    spawn at3b_ring();
    wait(1800);                                  // 到 TIME 5400
    spawn at4_ring();                            // 源此处不清弹
    wait(1800);                                  // 到 TIME 7200 (源 setInterrupt 超时)
    // 主任务返回 = Boss 退场, 伴生发弹任务被清杀; 尾弹自然离场
}

async sub boss_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 8000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, boss_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
